use Joomla\CMS\Factory;

/**
 * Optional example content (created only when the user asks for it):
 * an e-shop / hosting / maintenance offer template and its services.
 */
final class OfferSamples
{
    public static function install($db): int
    {
        $now = Factory::getDate()->toSql();
        $items = [];
        $ordering = 0;
        foreach (self::services() as $service) {
            $row = (object) [
                'kind'             => $service['kind'] ?? ($service['table'] || $service['price'] ? 'service' : 'description'),
                'name'             => $service['name'],
                'section_title'    => $service['section_title'],
                'table_label'      => $service['table_label'],
                'body'             => $service['body'],
                'price'            => $service['price'],
                'show_description' => $service['describe'],
                'in_table'         => $service['table'],
                'published'        => 1,
                'ordering'         => ++$ordering,
                'created'          => $now,
                'modified'         => $now,
            ];
            $db->insertObject('#__supportplans_offer_services', $row, 'id');
            $items[] = ['service_id' => (int) $row->id, 'show_description' => $service['describe'], 'in_table' => $service['table']];
        }

        $template = (object) [
            'name'          => 'E-shop + Φιλοξενία + Συντήρηση (παράδειγμα)',
            'doc_title'     => "Σχεδιασμός – Υλοποίηση e-shop\nΥπηρεσίες Φιλοξενίας & Συμβόλαιο Συντήρησης",
            'doc_subtitle'  => 'ΟΙΚΟΝΟΜΙΚΗ ΠΡΟΣΦΟΡΑ',
            'footer_title'  => 'Σχεδιασμός – Υλοποίηση e-shop, Υπηρεσίες Φιλοξενίας - Συμβόλαιο Συντήρησης',
            'vat_rate'      => 24,
            'show_banks'    => 1,
            'items'         => json_encode($items),
            'published'     => 1,
            'created'       => $now,
            'modified'      => $now,
        ];
        $db->insertObject('#__supportplans_offer_templates', $template, 'id');

        return (int) $template->id;
    }

